import {day,sum,groupRates,profileData,comparableEffect} from './intelligence.js';
import {deriveEffectiveness} from './analysis-core.js';

const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>Number.isFinite(x)?x.toLocaleString('en-US',{maximumFractionDigits:1}):'Unavailable';
const colors=['#995043','#2b2d41','#8f99ad','#d2b290','#626a80','#b9a69b'];
const names={quality:'Quality signals',trace:'Traceability',investigate:'Investigation',customers:'Customer feedback',containment:'Containment',recovery:'Recovery planner',cost:'Cost intelligence',capa:'CAPA command',learning:'Effectiveness',data:'Data workspace',expectedMissed:'Missed detections',expectedFalseHold:'False holds',handlingUnits:'Handling damage',inventory:'Stock',shipped:'Shipped',label:'Group',value:'Value',low:'95% lower limit',high:'95% upper limit',sample:'Inspected observations',defects:'Defective observations'};
const human=k=>names[k]||k;
const valid=x=>typeof x==='number'&&Number.isFinite(x);
const text=(x,y,value,extra='')=>`<text x="${x}" y="${y}" ${extra}>${escape(value)}</text>`;
const label=x=>String(x).length>29?String(x).slice(0,26)+'…':String(x);
const group=(rows,key,value=()=>1)=>{const m=new Map();for(const r of rows){const v=value(r);if(!valid(v))continue;const k=String(typeof key==='function'?key(r):r[key]||'Not supplied');m.set(k,(m.get(k)||0)+v)}return [...m].map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value)};
const dated=(rows,value)=>group(rows.filter(r=>r.date),'date',value).sort((a,b)=>a.label.localeCompare(b.label));
const stacked=(rows,key,parts)=>{const m=new Map();for(const r of rows){if(!parts.some(p=>valid(r[p])))continue;const k=String(typeof key==='function'?key(r):r[key]||'Not supplied');const g=m.get(k)||{label:k,...Object.fromEntries(parts.map(p=>[p,0]))};for(const p of parts)g[p]+=valid(r[p])?r[p]:0;m.set(k,g)}return [...m.values()]};

// Chart specifications contain only visible, exportable evidence. Missing values
// are never replaced with demonstration data or an inferred financial outcome.
export function visualSpecs(db,a,plans,selectedPlan){
  const specs=[],focus=a.focusRows,chosen=plans.find(p=>p.name===selectedPlan)||plans[0];
  const add=(id,view,title,note,kind,rows,unit,extra={})=>specs.push({id,view,title,note,kind,rows,unit,...extra});
  const rate=(id,view,title,field)=>add(id,view,title,`Selected defect: ${a.focus}. Defective observations / inspected observations; Wilson 95% intervals. Groups may differ in product and sampling mix.`, 'interval',groupRates(db,focus,field).map(g=>({label:g.label,value:g.rate,low:g.ci?.low,high:g.ci?.high,sample:g.sample,defects:g.defects})), '%');
  rate('factory-rates','quality','Factory defect rates and uncertainty','factory');
  rate('line-rates','quality','Line defect rates and uncertainty','line');
  rate('stage-rates','quality','Inspection-stage comparison','stage');
  rate('team-rates','quality','Production-team comparison','team');
  add('inspection-volume','quality','Inspection volume over time',`Selected defect: ${a.focus}. Daily sample observations; repeated inspections are not unique garments. Undated records omitted.`,'line',dated(focus,r=>r.sample),'inspected observations');
  add('severity-burden','quality','Observed defect burden by severity','All inspection records. Counts may include the same garment at multiple stages or defect types.','bar',group(db.inspections,'severity',r=>r.defects),'defective observations');
  add('exposure-stock','trace','Stock and shipped exposure by classification','Selected-defect scope. Known quantities only; missing quantities are omitted. Stock and shipped are distinct supplied batch quantities.','stack',stacked(a.exposure,'scope',['inventory','shipped']),'units',{parts:['inventory','shipped']});
  add('stock-location','trace','Where is related stock located?','Confirmed and precautionary batches. Known inventory only; unrelated stock excluded.','bar',group(a.exposure.filter(b=>['Confirmed','Precautionary'].includes(b.scope)),'location',b=>b.inventory),'stock units');
  add('shipment-status','trace','Shipment volume by status','All supplied shipment records, including planned shipments. Records are not added to batch inventory totals.','bar',group(db.shipments,'status',s=>s.units),'shipment units');
  add('shipment-market','trace','Shipment destination exposure','Shipment records linked to confirmed or precautionary batches. Includes planned shipments; not a delivered-unit count.','bar',group(db.shipments.filter(s=>a.exposure.some(b=>b.id===s.batch&&['Confirmed','Precautionary'].includes(b.scope))),'destination',s=>s.units),'shipment units');
  rate('machine-rates','investigate','Machine-group comparison','machine');
  rate('fabric-rates','investigate','Fabric-lot comparison','fabric');
  rate('thread-rates','investigate','Thread-lot comparison','thread');
  rate('shift-rates','investigate','Shift comparison','shift');
  const batchRates=groupRates(db,focus,'batch');
  add('speed-pattern','investigate','Machine speed versus observed defect rate','Supplied process conditions joined by batch to selected-defect observations. Multiple process records may share a rate. Association is not causation.','scatter',(db.processConditions||[]).flatMap(p=>{const r=batchRates.find(g=>g.label===p.batch);return r&&valid(p.speed)?[{label:p.batch+' · '+(p.operation||'operation'),x:p.speed,y:r.rate}]:[];}),'%',{xLabel:'Machine speed (recorded units/min)',yLabel:'Defective observations (%)'});
  add('complaint-categories','customers','Customer complaint mix','Counts of complaint records by current classification. Pending classifications remain unverified.','bar',group(db.complaints,'category'),'complaints');
  add('complaint-review','customers','Complaint review workload','All customer complaints grouped by recorded review decision.','bar',group(db.complaints,'decision'),'complaints');
  add('complaint-trend','customers','Customer signals over time','Daily complaint record count, not a complaint rate. Sales/use exposure denominator is not supplied. Undated records omitted.','line',dated(db.complaints,()=>1),'complaints');
  add('complaint-cost','customers','Recorded complaint cost by customer','Known complaint costs only. May overlap external-failure ledger totals; do not add the two totals.','bar',group(db.complaints,'customer',r=>r.cost),'USD');
  add('containment-status','containment','Containment commitment status','Recorded containment commitments; counts do not measure units physically quarantined.','bar',group(db.workspace?.containment||[],'status'),'commitments');
  add('containment-owner','containment','Open containment workload by owner','Incomplete containment commitments by responsible owner.','bar',group((db.workspace?.containment||[]).filter(c=>c.status!=='Complete'),'owner'),'open commitments');
  add('recovery-frontier','recovery','Recovery cost and lead-time trade-off','Model estimates under current capacity and calendar assumptions. Lower and left means less cost and time; exposure and release risk must also be reviewed.','scatter',plans.map((p,i)=>({label:`${i+1}. ${p.name}`,x:p.totalDays,y:p.cost})),'USD',{xLabel:'Recovery lead time (workdays)',yLabel:'Incremental recovery cost (USD)'});
  const costParts=['inspection','rework','replacement','reinspection','delay','holding','handling','transfer','scrap'];
  add('recovery-components','recovery','Selected recovery cost components',chosen?chosen.name+' · Estimated incremental costs; not recorded COPQ.':'Confirmed stock and complete inventory are needed to schedule recovery.','waterfall',chosen?costParts.map(k=>({label:k,value:chosen.costs[k]})):[],'USD');
  add('recovery-risk','recovery','Inspection error and handling assumptions','Expected quantities under supplied false-negative, false-positive and handling assumptions. Categories can overlap and must not be summed as affected garments.','multi',plans.map((p,i)=>({label:`${i+1}. ${p.name}`,expectedMissed:p.expectedMissed,expectedFalseHold:p.expectedFalseHold,handlingUnits:p.handlingUnits})),'expected units',{parts:['expectedMissed','expectedFalseHold','handlingUnits']});
  add('cutoff-release','recovery','Units released before shipment cut-off','Estimated priority/full release under each strategy. Missing shipment cut-off leaves this output unavailable.','bar',plans.map((p,i)=>({label:`${i+1}. ${p.name}`,value:p.unitsBeforeCutoff})),'units');
  add('cost-waterfall','cost','Recorded quality-cost bridge','Known category amounts only. Prevention and appraisal are quality costs; internal and external failures are strict COPQ. Missing categories make the total partial.','waterfall',a.costRows.map(([label,value])=>({label,value})),'USD');
  for(const [field,title] of [['factory','Factory'],['order','Order'],['supplier','Supplier']])add('ledger-'+field,'cost',title+' failure-cost attribution','Explicit ledger entries only; internal + external failure. Unallocated entries remain visible. No assumed allocation of aggregate cost.','bar',group((db.workspace?.costLedger||[]).filter(c=>['internal','external'].includes(c.category)),r=>r[field]||'Unallocated',r=>r.amount),'COPQ (USD)');
  add('intervention-value','cost','Intervention investment versus expected reduction','Stated estimates, not measured effectiveness. Confidence and resource implications remain in the intervention register.','scatter',db.interventions.map(i=>({label:i.name,x:i.cost,y:i.reduction})),'%',{xLabel:'Implementation investment (USD)',yLabel:'Expected defect reduction (%)'});
  add('action-status','capa','CAPA execution status','Counts of all incident actions by recorded status.','bar',group(db.actions,'status'),'actions');
  add('action-owner','capa','Outstanding workload by action owner','Actions not marked Done. Workload counts do not imply equivalent effort.','bar',group(db.actions.filter(a=>a.status!=='Done'),'owner'),'open actions');
  const daysUntil=due=>Math.round((Date.parse(due+'T00:00:00Z')-Date.parse(day()+'T00:00:00Z'))/86400000);
  add('action-deadlines','capa','Open-action deadline distribution',`Relative to ${day()} in Asia/Dhaka. Completed actions excluded.`,'bar',group(db.actions.filter(a=>a.status!=='Done'),r=>!r.due?'No due date':daysUntil(r.due)<0?'Overdue':daysUntil(r.due)<=7?'Due within 7 days':daysUntil(r.due)<=30?'Due in 8–30 days':'Due after 30 days'),'open actions');
  add('action-evidence','capa','Required-action assurance coverage','Required actions only. These checks overlap; each bar has the same required-action denominator. Completion alone does not establish closure readiness.','bar',[['Owner assigned',r=>r.owner],['Accountable assigned',r=>r.accountable],['Verifier assigned',r=>r.verifier],['Evidence recorded',r=>r.evidence],['Completed and dated',r=>r.status==='Done'&&r.completedAt]].map(([label,test])=>{const rows=db.actions.filter(r=>r.required);return {label,value:rows.length?rows.filter(test).length/rows.length*100:null}}),'% of required actions');
  const effect=deriveEffectiveness(db,a),c=comparableEffect(db,a,effect);
  add('matched-effect','learning','Comparable before-and-after uncertainty','Matched SKU, factory, line and overlapping inspection stages; Wilson 95% intervals. Missing identifiers cannot establish comparability.','interval',[{label:'Before action',...c.baseline},{label:'After action',...c.followup}].map(r=>({label:r.label,value:r.rate,low:r.ci?.low,high:r.ci?.high,sample:r.sample,defects:r.defects})),'%');
  add('verification-progress','learning','Verification checkpoints','Each checkpoint is either verified with required timing/evidence or pending. Pending is not evidence of ineffective action.','bar',Object.entries(effect.checks).map(([key,v])=>({label:key.slice(1)+'-day · '+(v.due||'implementation pending'),value:v.valid?1:0})),'verified (1) / pending (0)');
  add('data-coverage','data','Decision-input completeness','Share of records with each decision input supplied. Zero-record groups are unavailable, not 0% complete.','bar',profileData(db).coverage.map(r=>({label:r.label,value:r.percent})),'% complete');
  add('data-records','data','Imported evidence inventory','Record counts by collection. Different collection types are not additive as unique physical entities.','bar',['batches','inspections','shipments','complaints','actions','rework','orders','materials'].map(k=>({label:k,value:db[k]?.length??0})),'records');
  return specs.map(s=>({...s,source:db.sourceName,generated:day(),synthetic:!!db.groundTruth||db.sourceName==='enterprise-demonstration.json',rows:s.rows.filter(r=>s.kind==='scatter'?valid(r.x)&&valid(r.y):s.parts?s.parts.some(p=>valid(r[p])):valid(r.value))}));
}

function marks(s){
  const rows=s.rows, height=['bar','interval','stack','multi','waterfall'].includes(s.kind)?Math.max(240,rows.length*(s.kind==='multi'?58:37)+75):310;
  if(!rows.length)return {height:180,body:text(32,80,'Unavailable from the active data')+text(32,110,'Supply the required records or planning inputs to populate this chart.')};
  let body='';
  if(['bar','interval','waterfall','stack','multi'].includes(s.kind)){
    const waterfall=s.kind==='waterfall',parts=s.parts||[],multi=s.kind==='multi';
    const max=waterfall?sum(rows,'value'):Math.max(...rows.map(r=>s.kind==='interval'?r.high??r.value:s.kind==='stack'?parts.reduce((n,p)=>n+(r[p]||0),0):multi?Math.max(...parts.map(p=>r[p]||0)):r.value));
    const scale=370/Math.max(max,1),rowHeight=multi?58:37;
    for(let i=0;i<=4;i++){let x=204+i*92.5;body+=`<line x1="${x}" y1="25" x2="${x}" y2="${height-45}" stroke="#eee5df"/>`+text(x,height-24,fmt(Math.max(max,1)*i/4),'text-anchor="middle"');}
    let running=0;
    rows.forEach((r,i)=>{const y=40+i*rowHeight;body+=text(12,y+6,label(r.label));
      if(parts.length){let start=204;parts.forEach((p,j)=>{const value=r[p]||0,x=multi?204:start,yy=multi?y-10+j*12:y-8;body+=`<rect x="${x}" y="${yy}" width="${value*scale}" height="${multi?9:20}" rx="2" fill="${colors[j%colors.length]}"><title>${escape(r.label+' · '+p+': '+fmt(value)+' '+s.unit)}</title></rect>`;start+=value*scale});}
      else{const start=waterfall?running:0;body+=`<rect x="${204+start*scale}" y="${y-8}" width="${Math.max(0,r.value*scale)}" height="20" rx="2" fill="${colors[waterfall?i%colors.length:0]}"><title>${escape(r.label+': '+fmt(r.value)+' '+s.unit)}</title></rect>`;running+=r.value;
        if(s.kind==='interval'&&valid(r.low)&&valid(r.high))body+=`<path d="M${204+r.low*scale} ${y+2}H${204+r.high*scale} M${204+r.low*scale} ${y-4}v12 M${204+r.high*scale} ${y-4}v12" stroke="#2b2d41" stroke-width="2"/>`;
        body+=text(628,y+6,fmt(r.value),'text-anchor="end"');
      }
    });
    body+=text(390,height-3,s.unit,'text-anchor="middle"');
  }else{
    const scatter=s.kind==='scatter',dates=rows.map(r=>Date.parse(r.label+'T00:00:00Z'));
    const minX=scatter?0:Math.min(...dates),maxX=scatter?Math.max(1,...rows.map(r=>r.x)):Math.max(...dates),maxY=Math.max(1,...rows.map(r=>scatter?r.y:r.value))*1.1;
    const x=v=>70+(v-minX)/Math.max(1,maxX-minX)*490,y=v=>240-v/maxY*188;
    for(let i=0;i<=4;i++){const v=maxY*i/4;body+=`<line x1="70" y1="${y(v)}" x2="560" y2="${y(v)}" stroke="#eee5df"/>`+text(60,y(v)+4,fmt(v),'text-anchor="end"');}
    body+=text(70,23,s.yLabel||s.unit);
    if(!scatter)body+=`<polyline points="${rows.map((r,i)=>`${x(dates[i])},${y(r.value)}`).join(' ')}" fill="none" stroke="${colors[0]}" stroke-width="2.5"/>`;
    rows.forEach((r,i)=>{const xx=x(scatter?r.x:dates[i]),yy=y(scatter?r.y:r.value);body+=`<circle cx="${xx}" cy="${yy}" r="${scatter?6:4}" fill="${colors[0]}" stroke="white"><title>${escape(r.label+': '+(scatter?fmt(r.x)+' / '+fmt(r.y):fmt(r.value))+' '+s.unit)}</title></circle>`;if(scatter)body+=text(xx+9,yy-8,i+1);else if(i===0||i===rows.length-1||i%Math.max(1,Math.ceil(rows.length/5))===0)body+=text(xx,263,r.label.slice(5),'text-anchor="middle"');});
    if(scatter)for(let i=0;i<=4;i++)body+=text(x(maxX*i/4),263,fmt(maxX*i/4),'text-anchor="middle"');
    body+=text(315,296,s.xLabel||'Inspection / complaint date','text-anchor="middle"');
  }
  return {body,height};
}
function chart(s){const {body,height}=marks(s);return `<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${escape(s.title)}" viewBox="0 0 640 ${height}" class="visual-svg"><title>${escape(s.title)}</title><desc>${escape(s.note)}</desc><style>text{font:12px Arial,sans-serif;fill:#646b80}</style>${body}</svg>`;}
export function standaloneSvg(s){
  const {body,height}=marks(s),note=s.note.match(/.{1,90}(?:\s|$)|.{1,90}/g)||[];
  const key=s.kind==='scatter'?s.rows.flatMap((r,i)=>(String(i+1)+'. '+r.label).match(/.{1,90}(?:\s|$)|.{1,90}/g)||[]):s.parts||[];
  const bottom=height+90+note.length*17,total=bottom+key.length*18+30;
  return `<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${escape(s.title)}" viewBox="0 0 680 ${total}"><title>${escape(s.title)}</title><style>text{font:12px Arial,sans-serif;fill:#646b80}</style><rect width="680" height="${total}" fill="white"/>${text(20,30,s.title,'style="font-weight:bold;font-size:18px;fill:#2b2d41"')}${text(20,53,`${s.synthetic?'Synthetic demonstration · ':''}${s.source} · ${s.generated}`)}<g transform="translate(20,70)">${body}</g>${note.map((line,i)=>text(20,height+90+i*17,line)).join('')}${key.map((line,i)=>`${s.parts?`<rect x="20" y="${bottom+5+i*18}" width="10" height="10" fill="${colors[i%colors.length]}"/>`:''}${text(s.parts?38:20,bottom+15+i*18,s.parts?human(line):line)}`).join('')}</svg>`;
}
function evidence(s){const keys=[...new Set(s.rows.flatMap(Object.keys))];return `<details class="visual-evidence"><summary>Inspect chart data · ${s.rows.length} ${s.kind==='scatter'?'numbered points':s.rows.length===1?'group':'groups'}</summary><div class="table-wrap"><table><thead><tr>${s.kind==='scatter'?'<th>Point</th>':''}${keys.map(k=>`<th>${escape(human(k))}</th>`).join('')}</tr></thead><tbody>${s.rows.map((r,i)=>`<tr>${s.kind==='scatter'?`<td>${i+1}</td>`:''}${keys.map(k=>`<td>${escape(typeof r[k]==='number'?fmt(r[k]):r[k]??'Unavailable')}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
export function visualCard(s,interactive=true){return `<section class="panel visual-card" data-visual-id="${s.id}"><div class="panel-title"><div><h2>${escape(s.title)}</h2><p>${escape(s.note)}</p></div></div><div class="visual-plot">${chart(s)}</div>${s.parts?`<div class="visual-legend">${s.parts.map((p,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${escape(human(p))}</span>`).join('')}</div>`:''}<div class="visual-source">${s.synthetic?'Synthetic demonstration · ':''}Source: ${escape(s.source)} · ${s.generated}</div>${interactive?`<div class="visual-tools"><button class="btn" data-chart-svg="${s.id}">Download SVG</button><button class="btn" data-chart-csv="${s.id}">Download chart CSV</button></div>`:''}${evidence(s)}</section>`;}
export function visualsForView(view,db,a,plans,selectedPlan){const specs=visualSpecs(db,a,plans,selectedPlan).filter(s=>s.view===view);return specs.length?`<section class="visual-section"><div class="section-label"><h2>Visual analysis</h2><span>${specs.length} evidence-based views · <button class="text-button" data-view="visuals">Open visual library ↗</button></span></div><div class="visual-grid">${specs.map(s=>visualCard(s)).join('')}</div></section>`:'';}
export function visualLibrary(db,a,plans,selectedPlan,category='All',query=''){
  const all=visualSpecs(db,a,plans,selectedPlan),rows=all.filter(s=>(category==='All'||s.view===category)&&(!query||(s.title+' '+s.note).toLowerCase().includes(query.toLowerCase())));
  return `<div class="page-head"><div><div class="eyebrow">VISUAL INTELLIGENCE</div><h1>The evidence, in perspective.</h1><p>${all.length} analytical views from ${escape(db.sourceName)}. Inspection comparisons use ${escape(a.focus)}; other chart scopes are stated individually.</p></div><button class="btn primary" data-action="visual-report">Download visual report</button></div><div class="analysis-toolbar"><label>Defect<select id="focus-defect">${a.defects.map(d=>`<option value="${escape(d.type)}" ${d.type===a.focus?'selected':''}>${escape(d.type)}</option>`).join('')}</select></label><label>Reference batch<select id="focus-batch">${db.batches.map(b=>`<option value="${escape(b.id)}" ${b.id===a.reference.id?'selected':''}>${escape(b.id)}</option>`).join('')}</select></label><label>Workspace<select id="visual-category">${['All',...new Set(all.map(s=>s.view))].map(v=>`<option value="${v}" ${v===category?'selected':''}>${v==='All'?'All workspaces':human(v)}</option>`).join('')}</select></label><label>Find a visualization<input id="visual-search" type="search" value="${escape(query)}" placeholder="Search charts, e.g. cost"></label><strong>${rows.length} visualizations</strong></div><p class="chart-note">Charts with missing inputs explain what is unavailable. Hover plotted marks for exact values, expand chart data, or download individual SVG and CSV files. Overview display filters do not change this library; the selected defect and reference batch do.</p><div class="visual-grid">${rows.map(s=>visualCard(s)).join('')||'<div class="chart-empty">No visualizations match your search.</div>'}</div>`;
}
export const VISUAL_CSS=`.visual-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;align-items:start}.visual-card{min-width:0;break-inside:avoid}.visual-svg{width:100%;display:block}.visual-plot{max-height:560px;overflow:auto}.visual-source{font-size:11px;color:#646b80;margin:12px 0}.visual-tools{display:flex;gap:8px;margin-bottom:12px}.visual-evidence summary{cursor:pointer;color:#995043;font-size:12px}.visual-legend{display:flex;gap:14px;flex-wrap:wrap;font-size:11px}.visual-legend i{display:inline-block;width:10px;height:10px;margin-right:5px}.section-label{display:flex;justify-content:space-between;align-items:center;margin:30px 0 16px}.section-label h2{margin:0;font-size:20px}.section-label span{font-size:12px;color:#646b80}.visual-section{margin-bottom:28px}@media print{.visual-grid{display:block}.visual-card{margin-bottom:25px}.visual-tools{display:none}.visual-plot{max-height:none;overflow:visible}}`;
export function visualReport(db,a,plans,selectedPlan,fragment=false){const specs=visualSpecs(db,a,plans,selectedPlan);const body=`<style>${VISUAL_CSS}</style><h1>FactorySphere · Visual decision report</h1><p>${escape(db.sourceName)} · ${day()} · ${specs.length} visualizations · selected defect: ${escape(a.focus)}. Individual charts state scope, units and limitations.</p><div class="visual-grid">${specs.map(s=>visualCard(s,false)).join('')}</div>`;return fragment?body:`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>FactorySphere visual report</title><style>body{font:14px Arial,sans-serif;max-width:1400px;margin:32px auto;padding:24px;background:#f0e9e5;color:#2b2d41}.panel{background:white;border:1px solid #e6dcd4;border-radius:12px;padding:22px}.panel h2{font-size:18px}.panel p{font-size:12px;color:#646b80;line-height:1.5}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:8px;text-align:left;border-bottom:1px solid #e6dcd4}.table-wrap{overflow:auto}</style></head><body>${body}</body></html>`;}
export function chartCsv(s){const keys=[...new Set(s.rows.flatMap(Object.keys))];const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';return [[s.title],[s.note],['Source',s.source],['Generated',s.generated],['Unit',s.unit],keys,...s.rows.map(r=>keys.map(k=>r[k]))].map(row=>row.map(cell).join(',')).join('\r\n');}
